const input = $input.first().json;
const match = String(input.githubRepo || '').trim().match(/^([^/\s]+)\/([^/\s]+)$/);
if (!match) throw new Error('githubRepo must use owner/repository.');
if (!['EN','FR'].includes(String(input.language).toUpperCase())) throw new Error('language must be EN or FR.');
if (!/^https:\/\//.test(String(input.destinationWebhookUrl || ''))) throw new Error('destinationWebhookUrl must be HTTPS.');
const until = new Date();
const since = new Date(until.getTime() - 7 * 24 * 60 * 60 * 1000);
return [{ json: { ...input, owner: match[1], repo: match[2], language: String(input.language).toUpperCase(), since: since.toISOString(), until: until.toISOString() } }];

const config = $('Validate config and period').first().json;
const commits = $input.all().map(item => item.json).filter(commit => commit && commit.sha).map(commit => ({ sha: String(commit.sha).slice(0,7), message: commit.commit?.message?.split('\n')[0] || 'No commit message', author: commit.author?.login || commit.commit?.author?.name || 'unknown', date: commit.commit?.author?.date || null, url: commit.html_url || null }));
const activity = { repository: config.githubRepo, period: { start: config.since, end: config.until }, commitCount: commits.length, commits };
const language = config.language === 'FR' ? 'Write entirely in French.' : 'Write entirely in English.';
const prompt = language + ' You are preparing a factual weekly engineering digest for Slack. Use only the supplied evidence. Include an executive summary, a short list of changes, contributor signals where supported by the evidence, and a clear quiet-area note when there is no activity. Never invent issues, pull requests, incidents, or metrics. Use compact Markdown. Evidence: ' + JSON.stringify(activity);
return [{ json: { ...config, activity, prompt } }];

const result = $input.first().json;
const context = $('Build factual engineering evidence').first().json;
const narrative = (result.content || []).filter(part => part.type === 'text').map(part => part.text).join('\n').trim();
if (!narrative) throw new Error('Claude returned no narrative text.');
const heading = '*Engineering health digest — ' + context.githubRepo + '*';
return [{ json: { destinationWebhookUrl: context.destinationWebhookUrl, text: heading + '\n_Week ending ' + new Date(context.until).toISOString().slice(0,10) + '_\n' + narrative } }];
